<?php
require '/var/www/html/app/bootstrap.php';$bootstrap=\Magento\Framework\App\Bootstrap::create(BP,$_SERVER);$om=$bootstrap->getObjectManager();$om->get(\Magento\Framework\App\State::class)->setAreaCode('frontend');$om->get(\Magento\Store\Model\StoreManagerInterface::class)->setCurrentStore(1);
$collection=$om->get(\Magento\Catalog\Model\ResourceModel\Product\CollectionFactory::class)->create()->addAttributeToSelect('*')->addAttributeToFilter('status',1)->setOrder('sku','ASC');$rows=[];$catRepo=$om->get(\Magento\Catalog\Api\CategoryRepositoryInterface::class);
